import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 연결된 전표 상태가 '마감'이거나 연결된 결의서가 '완료'이면 마감·확정된 건으로 본다.
const CLOSED_VOUCHER_STATUS = '마감';
const CONFIRMED_RESOLUTION_STATUS = '완료';

@Controller('api/v1')
export class FnSfr00804Controller {
  @Post('/tax-invoices/change-issued')
  @HttpCode(200)
  async changeTaxInvoicesIssued(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자');
    const data = checks.inputOf(req.body);
    const rawIds = data['taxInvoiceIds'];
    if (!Array.isArray(rawIds) || rawIds.length === 0) {
      throw new ApiError(422, 'NO_TARGET_SELECTED', '변경할 세금계산서를 선택하세요.');
    }
    const issued = data['issued'];
    if (typeof issued !== 'boolean') {
      throw new ApiError(400, 'VALIDATION_FAILED', '발행 여부를 지정하세요.');
    }
    const ids: string[] = [];
    for (const raw of rawIds) {
      const n = typeof raw === 'number' || typeof raw === 'string' ? Number(raw) : NaN;
      if (!Number.isInteger(n) || n <= 0) {
        throw new ApiError(400, 'VALIDATION_FAILED', '세금계산서 ID 형식이 올바르지 않습니다.');
      }
      if (!ids.includes(String(n))) {
        ids.push(String(n));
      }
    }
    return transaction(async (db) => {
      let changedCount = 0;
      const failures: { taxInvoiceId: number; reason: string }[] = [];
      for (const id of ids) {
        const rows = await db.query(
          'SELECT t.tax_invoice_id AS "taxInvoiceId", jv.status AS "voucherStatus", er.approval_status AS "resolutionStatus" '
            + 'FROM tax_invoice t '
            + 'LEFT JOIN journal_voucher jv ON jv.journal_voucher_id = t.journal_voucher_id '
            + 'LEFT JOIN expense_resolution er ON er.expense_resolution_id = t.expense_resolution_id '
            + 'WHERE t.tax_invoice_id = CAST(:id AS bigint)',
          { id },
        );
        if (rows.length === 0) {
          failures.push({ taxInvoiceId: Number(id), reason: '존재하지 않는 전자세금계산서입니다.' });
          continue;
        }
        const row = rows[0];
        if (row['voucherStatus'] === CLOSED_VOUCHER_STATUS || row['resolutionStatus'] === CONFIRMED_RESOLUTION_STATUS) {
          failures.push({ taxInvoiceId: Number(id), reason: '마감·확정된 건이라 변경할 수 없습니다.' });
          continue;
        }
        const count = await db.execute(
          'UPDATE tax_invoice SET issued = :issued, updated_at = now() WHERE tax_invoice_id = CAST(:id AS bigint)',
          { id, issued },
        );
        changedCount += Number(count);
      }
      return { changedCount, failures };
    });
  }
}

