import { useState } from 'react';
import { Band, Badge, DataTable, Drawer, Field, Form, LookupSelect, RefName, Select, Tiles, call } from '../kit';
import type { PageProps, Row } from '../kit';

interface ChangeResult {
  changedCount: number;
  failures: { taxInvoiceId: number; reason: string }[];
}

export default function FnSfr00804Page({ role, notify }: PageProps) {
  const [open, setOpen] = useState(false);
  const [ids, setIds] = useState<number[]>([]);
  const [pick, setPick] = useState<number | string>('');
  const [issued, setIssued] = useState('');
  const [results, setResults] = useState<Row[]>([]);

  const successCount = results.filter((r) => r['result'] === '변경').length;
  const failCount = results.length - successCount;

  function openDrawer() {
    setIds([]);
    setPick('');
    setIssued('');
    setOpen(true);
  }

  function addTarget() {
    if (pick === '') {
      return;
    }
    const id = Number(pick);
    if (!ids.includes(id)) {
      setIds([...ids, id]);
    }
    setPick('');
  }

  async function submit() {
    if (ids.length === 0) {
      throw new Error('변경할 세금계산서를 선택하세요.');
    }
    if (issued === '') {
      throw new Error('발행 여부를 지정하세요.');
    }
    const res = await call<ChangeResult>('POST', '/tax-invoices/change-issued', role, {
      taxInvoiceIds: ids,
      issued: issued === 'true',
    });
    const failed = new Map<number, string>();
    for (const f of res.failures) {
      failed.set(Number(f.taxInvoiceId), f.reason);
    }
    const issuedText = issued === 'true' ? '발행' : '미발행';
    const rows: Row[] = ids.map((id) => ({
      taxInvoiceId: id,
      issuedText,
      result: failed.has(id) ? '제외' : '변경',
      reason: failed.get(id) ?? '',
    }));
    setResults([...rows, ...results]);
    notify('발행 여부를 ' + res.changedCount + '건 변경했습니다.');
    setOpen(false);
  }

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>변경 결과</h2>
        <Tiles items={[['변경 건수', successCount], ['제외 건수', failCount]]} />
      </section>
      <section className="box span-12">
        <h2>처리 내역</h2>
        <Band total={results.length}>
          <button type="button" onClick={openDrawer}>발행여부 일괄변경</button>
        </Band>
        <DataTable
          rows={results}
          empty="이 화면에서 처리한 내역이 없습니다."
          columns={[
            { key: 'taxInvoiceId', label: '전자세금계산서', render: (r) => <RefName table="tax_invoice" role={role} value={r['taxInvoiceId']} /> },
            { key: 'issuedText', label: '변경할 발행 여부' },
            { key: 'result', label: '결과', render: (r) => <Badge value={r['result']} /> },
            { key: 'reason', label: '사유' },
          ]}
        />
      </section>
      {open && (
        <Drawer title="발행여부 일괄변경" onClose={() => setOpen(false)}>
          <Form onSubmit={submit} submit="일괄 변경" note="마감·확정된 건은 제외되고 사유가 표시됩니다.">
            <Field label="변경 대상 전자세금계산서 ID 목록" required wide>
              <LookupSelect table="tax_invoice" role={role} value={pick} onChange={setPick} placeholder="세금계산서 선택" />
              <button type="button" onClick={addTarget}>대상 추가</button>
            </Field>
            <Field label="선택된 대상" wide>
              <div>
                {ids.length === 0 && <span>선택된 대상이 없습니다.</span>}
                {ids.map((id) => (
                  <div key={id}>
                    <RefName table="tax_invoice" role={role} value={id} />
                    <button type="button" onClick={() => setIds(ids.filter((x) => x !== id))}>제거</button>
                  </div>
                ))}
              </div>
            </Field>
            <Field label="발행 여부" required>
              <Select
                value={issued}
                onChange={setIssued}
                options={[['true', '발행'], ['false', '미발행']]}
              />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
